#import "P64Hardware.h"
#import <CoreBluetooth/CoreBluetooth.h>
#import <CoreFoundation/CoreFoundation.h>
#include <cmath>

static NSError *P64Err(NSString *s) { return [NSError errorWithDomain:@"P64Hardware" code:1 userInfo:@{NSLocalizedDescriptionKey:s}]; }
static BOOL P64Move(NSString *s) { if (!s || ![s isKindOfClass:NSString.class]) return NO; return [s rangeOfString:@"^[a-h][1-8][a-h][1-8][qrbn]?$" options:NSRegularExpressionSearch].location != NSNotFound; }
NSString *P64DecodeBoardPayload(NSData *data) {
    if (![data isKindOfClass:NSData.class]) return nil;
    if (data.length == 8) { const uint8_t *b=(const uint8_t *)data.bytes; NSMutableString *s=[NSMutableString stringWithCapacity:16]; for (int i=0;i<8;i++) [s appendFormat:@"%02x",b[i]]; return s; }
    NSString *s=[[NSString alloc] initWithData:data encoding:NSASCIIStringEncoding];
    if (P64Move(s)) return s;
    if (s.length == 16 && [s rangeOfString:@"^[0-9a-f]{16}$" options:NSRegularExpressionSearch].location != NSNotFound) return s;
    return nil;
}
BOOL P64OccupancyFromPayload(NSData *data, uint64_t *value) {
    NSString *s=P64DecodeBoardPayload(data); if (s.length != 16) return NO;
    uint64_t v=0; for (int i=0;i<8;i++) { unsigned int b=0; NSScanner *scanner=[NSScanner scannerWithString:[s substringWithRange:NSMakeRange(i*2,2)]]; if (![scanner scanHexInt:&b]) return NO; v |= ((uint64_t)b << (8*i)); } if (value) *value=v; return YES;
}
static BOOL P64Command(P64SystemCommand c) { return c>=P64SystemHome && c<=P64SystemReboot; }
static P64GantryStatus P64Status(NSInteger n) { return n>=0 && n<=3 ? (P64GantryStatus)n : P64GantryError; }
static void P64Main(dispatch_block_t b) { if (NSThread.isMainThread) b(); else dispatch_async(dispatch_get_main_queue(),b); }

@interface P64HardwareBase ()
@property(nonatomic) P64ConnectionStatus connectionStatus;
- (void)setLink:(P64ConnectionStatus)s;
- (void)board:(NSData *)data;
- (void)gantry:(P64GantryStatus)s;
@end
@implementation P64HardwareBase
- (void)setLink:(P64ConnectionStatus)s { if (_connectionStatus==s) return; _connectionStatus=s; if (_connectionUpdate) _connectionUpdate(s); }
- (void)board:(NSData *)data { if (P64DecodeBoardPayload(data) && _boardUpdate) _boardUpdate(data); }
- (void)gantry:(P64GantryStatus)s { if (_gantryUpdate) _gantryUpdate(s); }
- (void)connectToTarget:(NSString *)t completion:(void (^)(NSError *))c { c(P64Err(@"Unsupported")); }
- (void)disconnect {}
- (void)sendMove:(NSString *)s completion:(void (^)(NSError *))c { c(P64Err(@"Unsupported")); }
- (void)sendCommand:(P64SystemCommand)v completion:(void (^)(NSError *))c { c(P64Err(@"Unsupported")); }
@end

@interface P64MockHardwareBridge ()
@property NSUInteger generation;
@property P64GantryStatus state;
@property(nonatomic,copy) void (^pending)(NSError *);
@end
@implementation P64MockHardwareBridge
- (void)connectToTarget:(NSString *)target completion:(void (^)(NSError *))completion { P64Main(^{ NSUInteger previous=self.generation; [self disconnect]; if(self.generation!=previous+1) { completion(P64Err(@"Connection replaced")); return; } NSUInteger g=++self.generation; self.pending=completion; [self setLink:P64ConnectionConnecting]; if(g!=self.generation) return; dispatch_after(dispatch_time(DISPATCH_TIME_NOW,400*NSEC_PER_MSEC),dispatch_get_main_queue(),^{ if (g!=self.generation) return; void (^c)(NSError *)=self.pending; self.pending=nil; [self setLink:P64ConnectionConnected]; if(g!=self.generation) { if(c)c(P64Err(@"Connection replaced")); return; } self.state=P64GantryIdle; [self gantry:self.state]; if(c)c(g==self.generation ? nil : P64Err(@"Connection replaced")); }); }); }
- (void)disconnect { P64Main(^{ ++self.generation; void (^c)(NSError *)=self.pending; self.pending=nil; [self setLink:P64ConnectionDisconnected]; if(c)c(P64Err(@"Disconnected")); }); }
- (void)busy:(P64GantryStatus)s duration:(double)duration { NSUInteger g=++self.generation; self.state=s; [self gantry:s]; dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(duration*NSEC_PER_SEC)),dispatch_get_main_queue(),^{ if(g==self.generation && self.connectionStatus==P64ConnectionConnected) { self.state=P64GantryIdle; [self gantry:self.state]; } }); }
- (void)sendMove:(NSString *)move completion:(void (^)(NSError *))completion { P64Main(^{ if(self.connectionStatus!=P64ConnectionConnected || self.state!=P64GantryIdle || !P64Move(move)) { completion(P64Err(@"Disconnected, busy, or invalid move")); return; } int distance=MAX(abs([move characterAtIndex:0]-[move characterAtIndex:2]),abs([move characterAtIndex:1]-[move characterAtIndex:3])); [self busy:P64GantryMoving duration:0.7+distance*0.25]; completion(nil); }); }
- (void)sendCommand:(P64SystemCommand)command completion:(void (^)(NSError *))completion { P64Main(^{ if(self.connectionStatus!=P64ConnectionConnected || !P64Command(command) || (command==P64SystemHome && self.state!=P64GantryIdle && self.state!=P64GantryError)) { completion(P64Err(@"Disconnected, busy, or invalid command")); return; } if(command==P64SystemEmergencyStop) { ++self.generation; self.state=P64GantryIdle; [self gantry:self.state]; } else if(command==P64SystemHome) [self busy:P64GantryHoming duration:2]; else { [self disconnect]; [self connectToTarget:@"" completion:^(NSError *e) {}]; } completion(nil); }); }
- (void)simulateBoardPayload:(NSData *)payload { P64Main(^{ if(self.connectionStatus==P64ConnectionConnected) [self board:payload]; }); }
- (void)simulateFault { P64Main(^{ if(self.connectionStatus==P64ConnectionConnected) { ++self.generation; self.state=P64GantryError; [self gantry:self.state]; } }); }
@end

@interface P64BLEHardwareBridge () <CBCentralManagerDelegate, CBPeripheralDelegate>
@property(nonatomic,strong) CBCentralManager *manager;
@property(nonatomic,strong) CBPeripheral *peripheral;
@property(nonatomic,strong) CBCharacteristic *boardChar, *moveChar, *statusChar, *commandChar;
@property(nonatomic,copy) NSString *target;
@property(nonatomic,copy) void (^connectCompletion)(NSError *);
@property(nonatomic,copy) void (^moveCompletion)(NSError *);
@property(nonatomic,copy) void (^commandCompletion)(NSError *);
@property NSUInteger generation, moveWriteID, commandWriteID;
@end
@implementation P64BLEHardwareBridge
- (CBUUID *)uuid:(NSString *)s { return [CBUUID UUIDWithString:s]; }
- (void)finishConnect:(NSError *)error { void (^c)(NSError *)=self.connectCompletion; self.connectCompletion=nil; if(c)c(error); }
- (void)fail:(NSError *)error { ++self.generation; [self.manager stopScan]; if(self.peripheral) { self.peripheral.delegate=nil; [self.manager cancelPeripheralConnection:self.peripheral]; } self.manager.delegate=nil; self.manager=nil; self.peripheral=nil; self.boardChar=nil; self.moveChar=nil; self.statusChar=nil; self.commandChar=nil; void (^move)(NSError *)=self.moveCompletion; void (^command)(NSError *)=self.commandCompletion; self.moveCompletion=nil; self.commandCompletion=nil; void (^c)(NSError *)=self.connectCompletion; self.connectCompletion=nil; [self setLink:P64ConnectionDisconnected]; if(c)c(error); if(move)move(error); if(command)command(error); }
- (void)disconnect { P64Main(^{ [self fail:P64Err(@"Disconnected")]; }); }
- (void)connectToTarget:(NSString *)target completion:(void (^)(NSError *))completion { P64Main(^{ NSUInteger previous=self.generation; [self fail:P64Err(@"Connection replaced")]; if(self.generation!=previous+1) { completion(P64Err(@"Connection replaced")); return; } self.target=target ?: @""; self.connectCompletion=completion; NSUInteger g=++self.generation; [self setLink:P64ConnectionScanning]; if(g!=self.generation) return; if(!self.manager) self.manager=[[CBCentralManager alloc] initWithDelegate:self queue:dispatch_get_main_queue()]; else [self centralManagerDidUpdateState:self.manager]; dispatch_after(dispatch_time(DISPATCH_TIME_NOW,15*NSEC_PER_SEC),dispatch_get_main_queue(),^{ if(g==self.generation && self.connectCompletion) [self fail:P64Err(@"Bluetooth connection timed out")]; }); }); }
- (void)centralManagerDidUpdateState:(CBCentralManager *)central { if(central!=self.manager || !self.connectCompletion || self.connectionStatus!=P64ConnectionScanning) return; if(central.state==CBManagerStatePoweredOn) [central scanForPeripheralsWithServices:@[[self uuid:@"CB00"]] options:nil]; else if(central.state==CBManagerStatePoweredOff || central.state==CBManagerStateUnauthorized || central.state==CBManagerStateUnsupported) [self fail:P64Err(@"Bluetooth unavailable")]; }
- (void)centralManager:(CBCentralManager *)central didDiscoverPeripheral:(CBPeripheral *)p advertisementData:(NSDictionary *)ad RSSI:(NSNumber *)rssi { if(central!=self.manager || !self.connectCompletion || self.connectionStatus!=P64ConnectionScanning) return; NSString *local=ad[CBAdvertisementDataLocalNameKey]; if(self.target.length && ![self.target isEqualToString:p.name] && ![self.target isEqualToString:local] && [self.target caseInsensitiveCompare:p.identifier.UUIDString]!=NSOrderedSame) return; NSUInteger g=self.generation; [central stopScan]; self.peripheral=p; p.delegate=self; [self setLink:P64ConnectionConnecting]; if(g!=self.generation || p!=self.peripheral || !self.connectCompletion) return; [central connectPeripheral:p options:nil]; }
- (void)centralManager:(CBCentralManager *)central didConnectPeripheral:(CBPeripheral *)p { if(central==self.manager && p==self.peripheral && self.connectCompletion && self.connectionStatus==P64ConnectionConnecting) [p discoverServices:@[[self uuid:@"CB00"]]]; }
- (void)centralManager:(CBCentralManager *)central didFailToConnectPeripheral:(CBPeripheral *)p error:(NSError *)e { if(central==self.manager && p==self.peripheral && self.connectCompletion && self.connectionStatus==P64ConnectionConnecting) [self fail:e ?: P64Err(@"Bluetooth connection failed")]; }
- (void)centralManager:(CBCentralManager *)central didDisconnectPeripheral:(CBPeripheral *)p error:(NSError *)e { if(central==self.manager && p==self.peripheral) [self fail:e ?: P64Err(@"Bluetooth disconnected")]; }
- (void)peripheral:(CBPeripheral *)p didDiscoverServices:(NSError *)e { if(p!=self.peripheral)return; if(e || !p.services.count) { [self fail:e ?: P64Err(@"Service missing")]; return; } for(CBService *s in p.services) if([s.UUID isEqual:[self uuid:@"CB00"]]) { [p discoverCharacteristics:@[[self uuid:@"CB01"],[self uuid:@"CB02"],[self uuid:@"CB03"],[self uuid:@"CB04"]] forService:s]; return; } [self fail:P64Err(@"Service missing")]; }
- (void)peripheral:(CBPeripheral *)p didDiscoverCharacteristicsForService:(CBService *)s error:(NSError *)e { if(p!=self.peripheral)return; if(e) { [self fail:e]; return; } for(CBCharacteristic *c in s.characteristics) { if([c.UUID isEqual:[self uuid:@"CB01"]]) self.boardChar=c; else if([c.UUID isEqual:[self uuid:@"CB02"]]) self.moveChar=c; else if([c.UUID isEqual:[self uuid:@"CB03"]]) self.statusChar=c; else if([c.UUID isEqual:[self uuid:@"CB04"]]) self.commandChar=c; } if(!self.boardChar || !self.moveChar || !self.statusChar || !self.commandChar || !(self.moveChar.properties & CBCharacteristicPropertyWrite) || !(self.commandChar.properties & CBCharacteristicPropertyWrite) || !(self.boardChar.properties & CBCharacteristicPropertyNotify) || !(self.statusChar.properties & CBCharacteristicPropertyNotify)) { [self fail:P64Err(@"Required Bluetooth characteristics unavailable")]; return; } [p setNotifyValue:YES forCharacteristic:self.boardChar]; [p setNotifyValue:YES forCharacteristic:self.statusChar]; }
- (void)peripheral:(CBPeripheral *)p didUpdateNotificationStateForCharacteristic:(CBCharacteristic *)c error:(NSError *)e { if(p!=self.peripheral)return; if(e || !c.isNotifying) { NSUInteger g=self.generation; if(c==self.statusChar && self.connectionStatus==P64ConnectionConnected) [self gantry:P64GantryError]; if(g==self.generation) [self fail:e ?: P64Err(@"Bluetooth notifications unavailable")]; return; } if(self.boardChar.isNotifying && self.statusChar.isNotifying && self.connectCompletion) { NSUInteger g=self.generation; [self setLink:P64ConnectionConnected]; if(g!=self.generation) return; [self finishConnect:nil]; if(g!=self.generation || p!=self.peripheral) return; if(self.statusChar.properties & CBCharacteristicPropertyRead) [p readValueForCharacteristic:self.statusChar]; } }
- (void)peripheral:(CBPeripheral *)p didUpdateValueForCharacteristic:(CBCharacteristic *)c error:(NSError *)e { if(p!=self.peripheral)return; if(c==self.statusChar && e) { [self gantry:P64GantryError]; return; } if(e)return; if(c==self.boardChar) [self board:c.value]; else if(c==self.statusChar) { const uint8_t *b=(const uint8_t *)c.value.bytes; [self gantry:c.value.length==1 ? P64Status(b[0]) : P64GantryError]; } }
- (void)peripheral:(CBPeripheral *)p didWriteValueForCharacteristic:(CBCharacteristic *)c error:(NSError *)e { if(p!=self.peripheral)return; void (^done)(NSError *)=nil; if(c==self.moveChar) { done=self.moveCompletion; self.moveCompletion=nil; } else if(c==self.commandChar) { done=self.commandCompletion; self.commandCompletion=nil; } if(done)done(e); }
- (void)write:(NSData *)data characteristic:(CBCharacteristic *)characteristic completion:(void (^)(NSError *))completion { BOOL move=characteristic && characteristic==self.moveChar; BOOL command=characteristic && characteristic==self.commandChar; if(self.connectionStatus!=P64ConnectionConnected || (!move && !command) || (move ? self.moveCompletion!=nil : self.commandCompletion!=nil)) { completion(P64Err(@"Bluetooth disconnected or busy")); return; } NSUInteger writeID; if(move) { self.moveCompletion=completion; writeID=++self.moveWriteID; } else { self.commandCompletion=completion; writeID=++self.commandWriteID; } NSUInteger g=self.generation; [self.peripheral writeValue:data forCharacteristic:characteristic type:CBCharacteristicWriteWithResponse]; dispatch_after(dispatch_time(DISPATCH_TIME_NOW,10*NSEC_PER_SEC),dispatch_get_main_queue(),^{ BOOL pending=move ? (writeID==self.moveWriteID && self.moveCompletion!=nil) : (writeID==self.commandWriteID && self.commandCompletion!=nil); if(g==self.generation && pending) [self fail:P64Err(@"Bluetooth write timed out")]; }); }
- (void)sendMove:(NSString *)move completion:(void (^)(NSError *))completion { P64Main(^{ if(!P64Move(move)) { completion(P64Err(@"Invalid move")); return; } [self write:[move dataUsingEncoding:NSASCIIStringEncoding] characteristic:self.moveChar completion:completion]; }); }
- (void)sendCommand:(P64SystemCommand)c completion:(void (^)(NSError *))completion { P64Main(^{ if(!P64Command(c)) { completion(P64Err(@"Invalid command")); return; } uint8_t b=c; [self write:[NSData dataWithBytes:&b length:1] characteristic:self.commandChar completion:completion]; }); }
@end

@interface P64WiFiHardwareBridge () <NSURLSessionWebSocketDelegate>
@property(nonatomic,strong) NSURLSession *session;
@property(nonatomic,strong) NSURLSessionWebSocketTask *socket;
@property(nonatomic,copy) NSString *host;
@property(nonatomic,copy) void (^connectCompletion)(NSError *);
@property(nonatomic,strong) NSMutableDictionary<NSNumber *,void (^)(NSError *)> *pending;
@property NSUInteger generation, nextWrite;
@end
@implementation P64WiFiHardwareBridge
- (instancetype)init { if((self=[super init])) _pending=[NSMutableDictionary dictionary]; return self; }
- (void)finishConnect:(NSError *)e { void (^c)(NSError *)=self.connectCompletion; self.connectCompletion=nil; if(c)c(e); }
- (void)disconnect { P64Main(^{ ++self.generation; [self.socket cancelWithCloseCode:NSURLSessionWebSocketCloseCodeGoingAway reason:nil]; self.socket=nil; [self.session invalidateAndCancel]; self.session=nil; self.host=nil; void (^connect)(NSError *)=self.connectCompletion; self.connectCompletion=nil; NSArray *callbacks=self.pending.allValues; [self.pending removeAllObjects]; [self setLink:P64ConnectionDisconnected]; if(connect)connect(P64Err(@"Disconnected")); for(void (^c)(NSError *) in callbacks) c(P64Err(@"Disconnected")); }); }
- (void)connectToTarget:(NSString *)target completion:(void (^)(NSError *))completion { P64Main(^{ NSUInteger previous=self.generation; [self disconnect]; if(self.generation!=previous+1) { completion(P64Err(@"Connection replaced")); return; } NSString *host=[target stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet]; // A port is accepted only for localhost/127.0.0.1 and maps both transports to that port.
 NSRegularExpression *re=[NSRegularExpression regularExpressionWithPattern:@"^(?:[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?)(?::[0-9]{1,5})?$" options:0 error:nil]; if(!host.length || [re numberOfMatchesInString:host options:0 range:NSMakeRange(0,host.length)]!=1) { completion(P64Err(@"Invalid host")); return; } NSArray *parts=[host componentsSeparatedByString:@":"]; for(NSString *label in [parts[0] componentsSeparatedByString:@"."]) { if(!label.length || label.length>63 || [label hasPrefix:@"-"] || [label hasSuffix:@"-"]) { completion(P64Err(@"Invalid host")); return; } } if(parts.count>1 && (!([parts[0] isEqualToString:@"localhost"] || [parts[0] isEqualToString:@"127.0.0.1"]) || [parts[1] integerValue]<1 || [parts[1] integerValue]>65535)) { completion(P64Err(@"Invalid host port")); return; } self.host=host; self.connectCompletion=completion; NSUInteger g=++self.generation; [self setLink:P64ConnectionConnecting]; if(g!=self.generation) return; self.session=[NSURLSession sessionWithConfiguration:NSURLSessionConfiguration.defaultSessionConfiguration delegate:self delegateQueue:NSOperationQueue.mainQueue]; NSString *authority=parts.count>1 ? host : [host stringByAppendingString:@":81"]; self.socket=[self.session webSocketTaskWithURL:[NSURL URLWithString:[NSString stringWithFormat:@"ws://%@/ws",authority]]]; [self.socket resume]; dispatch_after(dispatch_time(DISPATCH_TIME_NOW,5*NSEC_PER_SEC),dispatch_get_main_queue(),^{ if(g==self.generation && self.connectCompletion) { [self.socket cancelWithCloseCode:NSURLSessionWebSocketCloseCodeGoingAway reason:nil]; self.socket=nil; void (^c)(NSError *)=self.connectCompletion; self.connectCompletion=nil; [self setLink:P64ConnectionDisconnected]; if(c)c(P64Err(@"WebSocket connection timed out")); } }); }); }
- (void)URLSession:(NSURLSession *)session webSocketTask:(NSURLSessionWebSocketTask *)task didOpenWithProtocol:(NSString *)protocol { if(session!=self.session || task!=self.socket)return; NSUInteger g=self.generation; [self setLink:P64ConnectionConnected]; if(g!=self.generation || task!=self.socket) return; [self finishConnect:nil]; if(g==self.generation && task==self.socket) [self receive:task generation:g]; }
