- (void)URLSession:(NSURLSession *)session webSocketTask:(NSURLSessionWebSocketTask *)task didCloseWithCode:(NSURLSessionWebSocketCloseCode)code reason:(NSData *)reason { [self closed:task error:nil]; }
- (void)URLSession:(NSURLSession *)session task:(NSURLSessionTask *)task didCompleteWithError:(NSError *)error { if([task isKindOfClass:NSURLSessionWebSocketTask.class]) [self closed:(NSURLSessionWebSocketTask *)task error:error]; }
- (void)receive:(NSURLSessionWebSocketTask *)task generation:(NSUInteger)g { __weak __typeof__(self) weakSelf=self; [task receiveMessageWithCompletionHandler:^(NSURLSessionWebSocketMessage *message,NSError *error) { P64Main(^{ __typeof__(self) self=weakSelf; if(!self || g!=self.generation || task!=self.socket)return; if(error) { [self closed:task error:error]; return; } NSData *data=message.type==NSURLSessionWebSocketMessageTypeString ? [message.string dataUsingEncoding:NSUTF8StringEncoding] : message.data; id object=data ? [NSJSONSerialization JSONObjectWithData:data options:NSJSONReadingFragmentsAllowed error:nil] : nil; if([object isKindOfClass:NSDictionary.class]) { id type=object[@"type"], value=object[@"data"]; if([type isEqual:@"board"] && [value isKindOfClass:NSString.class]) { NSString *s=[value lowercaseString]; [self board:[s dataUsingEncoding:NSASCIIStringEncoding]]; } else if([type isEqual:@"status"] && [value isKindOfClass:NSNumber.class]) { double n=[value doubleValue]; BOOL valid=CFGetTypeID((__bridge CFTypeRef)value)!=CFBooleanGetTypeID() && std::isfinite(n) && std::floor(n)==n && n>=0 && n<=3; [self gantry:valid ? P64Status((NSInteger)n) : P64GantryError]; } } [self receive:task generation:g]; }); }]; }
- (void)sendType:(NSString *)type value:(id)value completion:(void (^)(NSError *))completion { if(!self.host) { completion(P64Err(@"No Wi-Fi target")); return; } NSData *body=[NSJSONSerialization dataWithJSONObject:@{@"type":type,@"data":value} options:0 error:nil]; NSNumber *key=@(++self.nextWrite); self.pending[key]=completion; NSUInteger g=self.generation; __weak __typeof__(self) weakSelf=self; void (^finish)(NSError *)=^(NSError *e){ P64Main(^{ __typeof__(self) self=weakSelf; if(!self || self.generation!=g)return; void (^c)(NSError *)=self.pending[key]; [self.pending removeObjectForKey:key]; if(c)c(e); }); }; dispatch_after(dispatch_time(DISPATCH_TIME_NOW,15*NSEC_PER_SEC),dispatch_get_main_queue(),^{ finish(P64Err(@"Wi-Fi write timed out")); }); if(self.socket && self.connectionStatus==P64ConnectionConnected) { NSString *text=[[NSString alloc] initWithData:body encoding:NSUTF8StringEncoding]; [self.socket sendMessage:[[NSURLSessionWebSocketMessage alloc] initWithString:text] completionHandler:finish]; } else { NSMutableURLRequest *request=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:[NSString stringWithFormat:@"http://%@/api",self.host]]]; request.HTTPMethod=@"POST"; request.HTTPBody=body; [request setValue:@"application/json" forHTTPHeaderField:@"Content-Type"]; [[self.session dataTaskWithRequest:request completionHandler:^(NSData *data,NSURLResponse *response,NSError *error) { NSInteger code=[(NSHTTPURLResponse *)response statusCode]; finish(error ?: (code>=200 && code<300 ? nil : P64Err(@"HTTP request failed"))); }] resume]; } }
- (void)sendMove:(NSString *)move completion:(void (^)(NSError *))completion { P64Main(^{ if(!P64Move(move)) { completion(P64Err(@"Invalid move")); return; } [self sendType:@"move" value:move completion:completion]; }); }
- (void)sendCommand:(P64SystemCommand)command completion:(void (^)(NSError *))completion { P64Main(^{ if(!P64Command(command)) { completion(P64Err(@"Invalid command")); return; } [self sendType:@"cmd" value:@(command) completion:completion]; }); }
@end
